INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT135-S1-Q7$batch08$, 135, 1, 7, $batch08$Most Strongly Supported$batch08$, $batch08$Economist: Government intervention in the free market in pursuit of socially desirable goals can affect supply and demand, thereby distorting prices. The ethics of such intervention is comparable to that of administering medicines. Most medicines have harmful as well as beneficial effects, so the use of a type of medicine is ethically justified only when its nonuse would be significantly more harmful than its use. Similarly, government intervention in the free market is justified only when it _______.$batch08$, $batch08$Which one of the following most logically completes the final sentence above?$batch08$, $batch08$D$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=135 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$would likely be approved of by the majority of the affected participants$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$has been shown to have few if any significantly harmful effects$batch08$, $batch08$Opposite$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$is believed unlikely to significantly exacerbate any existing problems$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$would do less damage than would result from the government’s not intervening$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$provides a solution to some otherwise insoluble problem$batch08$, $batch08$Too Strong$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Government intervention can distort prices. Its ethics are like those of medicine. Most medicines do harm and good, so a medicine is justified only when not using it would be significantly more harmful than using it. "Similarly," intervention is justified only when it ___.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$"Similarly" tells you to copy the medicine rule onto intervention. The medicine rule compares two harms: the harm of using it and the harm of not using it. So intervention is justified only when not intervening would be worse than intervening.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Intervention does less damage than not intervening.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Approval by the majority has nothing to do with the medicine rule.$batch08$), ($batch08$B$batch08$, $batch08$Medicines have harmful effects and can still be justified. The rule doesn't demand few harms; it compares harms.$batch08$), ($batch08$C$batch08$, $batch08$This looks at one side only, whether intervening makes things worse. The rule compares intervening with not intervening.$batch08$), ($batch08$D$batch08$, $batch08$It is the medicine rule, copied over: justified only when not acting would do more damage.$batch08$), ($batch08$E$batch08$, $batch08$Nothing requires the problem to be otherwise unsolvable.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT135-S1-Q7$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
